"""Original integrated assessments: reading, listening, contextual language and transfer."""
import json
from pathlib import Path
items=[]
def add(level,title,reading,translation,listen,listen_es,rows,writing,speaking,role):
 qs=[]
 for i,(prompt,answer,w1,w2,why) in enumerate(rows):
  skill='reading' if i<4 else 'listening' if i<7 else 'use'
  qs.append(dict(id=f'u1-as1{i}',unit=1,skill=skill,type='choice',prompt=prompt,answer=answer,options=[answer,w1,w2],why=why,passage=reading if skill=='reading' else '',audio=listen if skill=='listening' else ''))
 items.append(dict(id=f'{level}-1',level=level,block='all',title=title,reading=reading,translation=translation,listening=dict(text=listen,translation=listen_es,role=role),questions=qs,writing=writing,speaking=speaking))
add('a1','El primer sábado de Alex',
'''Alex is new in town. On Saturday, he meets Mia at the library. The library opens at nine, but they meet at ten. Alex wants a book about animals. Mia wants a book for her little brother. After the library, they walk to a small café next to the park. Alex has tea and a sandwich. Mia has water because she does not like tea. The café is quiet in the morning. At twelve, Mia goes home. Alex stays in the park and reads his new book.''',
'''Alex es nuevo en la ciudad. El sábado se reúne con Mia en la biblioteca. La biblioteca abre a las nueve, pero ellos quedan a las diez. Alex quiere un libro sobre animales. Mia quiere uno para su hermano pequeño. Después caminan a un café junto al parque. Alex toma té y un sándwich. Mia toma agua porque no le gusta el té. El café es tranquilo por la mañana. A las doce Mia vuelve a casa. Alex se queda en el parque y lee su nuevo libro.''',
'''Hi Alex, it's Mia. The library is next to the school, not next to the station. Bring your library card. We can have lunch in the park if the weather is good. I have some apples. Can you bring two sandwiches? See you at ten!''',
'''Hola Alex, soy Mia. La biblioteca está junto a la escuela, no junto a la estación. Trae tu carné. Podemos almorzar en el parque si hace buen tiempo. Tengo unas manzanas. ¿Puedes traer dos sándwiches? ¡Nos vemos a las diez!''',[
('¿Qué describe el texto?','A morning with a new friend','A day at school','A family holiday','Los dos visitan la biblioteca y un café durante la mañana.'),
('¿A qué hora se encuentran?','At ten','At nine','At twelve','La apertura es a las nueve, pero «they meet at ten» indica la cita.'),
('¿Para quién busca Mia un libro?','For her brother','For Alex','For her teacher','«for her little brother» identifica a la persona destinataria.'),
('¿Por qué toma agua Mia?','She does not like tea','The café has no tea','She has no money','La razón aparece con because: no le gusta el té.'),
('Según el mensaje, ¿dónde está la biblioteca?','Next to the school','Next to the station','In the park','Mia corrige la confusión: está junto a la escuela.'),
('¿Qué comida debe llevar Alex?','Two sandwiches','Some apples','A cake','Mia tiene las manzanas y pide a Alex dos sándwiches.'),
('¿De qué depende almorzar en el parque?','The weather','The library card','The price of tea','La condición es «if the weather is good»: si hace buen tiempo.'),
('Completa: Mia ___ water at the café.','has','have','having','Con Mia (she) usamos has en presente simple.'),
('Quieres pedir un sándwich amablemente.','Can I have a sandwich, please?','I am a sandwich.','Where sandwich yesterday?','Can I have…? sirve para pedir algo; please aporta cortesía.'),
('Completa: They meet ___ ten.','at','on','in','Usamos at para una hora concreta: at ten.')],
'Escribe 30–45 palabras para invitar a alguien a una biblioteca o un café. Incluye lugar, día, hora y una pregunta.',
'En 20–30 segundos, preséntate y propón algo para el sábado. Di dónde y a qué hora.','Mia')
add('a2','La maleta que llegó después',
'''When Ella arrived in Bristol on Friday, her suitcase was missing. She went to the airline desk and filled in a form. The assistant said the suitcase was still in Paris and would arrive the next morning. Ella was staying with her cousin, Oliver, for the weekend. She only had her phone, a book and a light jacket in her small bag. Oliver lent her a clean shirt and took her to a shop for a toothbrush. On Saturday morning, the airline called. They offered to send the suitcase to Oliver's flat between two and four. Ella and Oliver had planned to visit a museum, but they changed their plans. They visited a nearby market in the morning and went to the museum on Sunday. The suitcase arrived at half past three, with everything inside.''',
'''Ella llegó a Bristol el viernes, pero faltaba su maleta. Rellenó un formulario en el mostrador. Le dijeron que la maleta seguía en París y llegaría al día siguiente. Se quedaba el fin de semana con su primo Oliver. En el bolso tenía el móvil, un libro y una chaqueta. Oliver le prestó una camisa y la llevó a comprar un cepillo. El sábado la aerolínea ofreció llevar la maleta al piso entre las dos y las cuatro. Cambiaron su plan de ir al museo: fueron al mercado por la mañana y al museo el domingo. La maleta llegó a las tres y media con todo dentro.''',
'''Hello, this is the airline delivery team. We are calling about Ella's suitcase. Our driver is running late and will arrive at about five, not before four as we said earlier. If nobody can be at the flat, we can leave the suitcase with the building manager. Please call us before three to tell us what you prefer.''',
'''Hola, somos el equipo de entregas. Llamamos por la maleta de Ella. El conductor va con retraso y llegará sobre las cinco, no antes de las cuatro como dijimos. Si no puede haber nadie en el piso, podemos dejarla con el encargado. Llámenos antes de las tres para decirnos qué prefiere.''',[
('¿Qué problema tuvo Ella?','Her suitcase did not arrive with her','She lost her phone','Her cousin was away','La maleta seguía en París cuando Ella ya estaba en Bristol.'),
('¿Cómo la ayudó Oliver al principio?','He lent her a shirt','He bought her a suitcase','He flew to Paris','Lent significa prestó; también la acompañó a comprar un cepillo.'),
('¿Por qué cambiaron la visita al museo?','They needed to wait for the delivery','The museum was closed','Tickets were too expensive','La entrega entre las dos y las cuatro condicionó sus planes.'),
('¿Cuál es el orden de los hechos del texto?','Market, suitcase delivery, museum','Museum, market, suitcase delivery','Suitcase delivery, museum, market','Mercado el sábado por la mañana, entrega por la tarde y museo el domingo.'),
('¿Para qué llama el equipo de entregas?','To change the delivery arrangements','To sell Ella another ticket','To say the suitcase is lost forever','El nuevo mensaje actualiza el horario y ofrece una alternativa.'),
('¿Cuál es la nueva hora aproximada?','Five o’clock','Three o’clock','Two o’clock','Five es la nueva hora; three es el límite para responder.'),
('¿Qué debe hacer Ella antes de las tres?','Call with her preference','Visit the museum','Go to the airport','Debe comunicar si prefiere la entrega personal o al encargado.'),
('Completa: Oliver ___ her a shirt yesterday.','lent','lends','lending','Yesterday sitúa la acción en pasado. Lend cambia a lent.'),
('Completa: They changed their plans ___ the delivery.','because of','because','so that','Because of va con un nombre; because requiere una oración.'),
('Necesitas que repitan la hora de entrega.','Could you repeat the time, please?','You must have a time.','I repeat yesterday.','Could you repeat…? permite pedir aclaración con cortesía.')],
'Escribe 60–80 palabras a la aerolínea: resume el problema, indica cuándo estarás en casa y pide confirmar la entrega.',
'En 45 segundos, explica un problema de viaje y cómo cambiaste tus planes.','Oliver')
add('b1','Una manera de colaborar',
'''Mia joined a volunteer group that repaired old computers for local families. The group met every Thursday evening. Although members were friendly, new volunteers often left after a few weeks. Mia noticed that experienced members used technical terms without explaining them. Beginners spent much of the evening watching because they were afraid of damaging something. She suggested pairing each beginner with an experienced volunteer for the first three sessions. Some members worried that this would slow down repairs. The coordinator agreed to try the idea for a month rather than change the whole system immediately. Mia prepared a short checklist with pictures, but she deliberately left space for questions instead of writing a long manual. At the end of the month, the group had repaired slightly fewer computers, yet more beginners were able to complete simple tasks on their own. The coordinator decided to keep the pairs and review repair numbers after three months. Mia learned that a useful change can have a short-term cost, and that explaining the purpose of a change helps other people support it.''',
'''Mia entró en un grupo que reparaba ordenadores para familias. Muchos principiantes se iban pronto. Observó términos técnicos sin explicar y miedo a estropear algo. Propuso acompañar a cada nuevo voluntario durante tres sesiones. Algunos temían ralentizar las reparaciones. La coordinadora aceptó probarlo un mes. Mia preparó una lista breve con imágenes y espacio para preguntas. Repararon algo menos, pero más principiantes pudieron hacer tareas solos. Mantuvieron las parejas y acordaron revisar las cifras a los tres meses. Mia aprendió que una mejora puede tener un coste inicial y que explicar su propósito facilita el apoyo.''',
'''Hi Mia, I've read the feedback. The beginners liked working in pairs, but two said they never knew what to practise next. Could you add a small section to the checklist where partners agree on one goal for the following week? Please keep the existing pictures. We can discuss your draft on Thursday; there is no need to print copies yet.''',
'''Hola Mia, he leído los comentarios. A los principiantes les gustó trabajar en parejas, pero dos no sabían qué practicar después. Añade una sección para acordar un objetivo de la semana siguiente. Conserva las imágenes. Veremos el borrador el jueves; aún no hace falta imprimir.''',[
('¿Qué problema intenta resolver la propuesta?','Beginners do not become confident participants','There are too many donated computers','Experienced volunteers cannot use computers','La falta de explicaciones y el miedo impedían a los principiantes participar.'),
('¿Por qué algunos miembros dudaban?','Repairs might become slower','The room was too small','Beginners would have to pay','La preocupación explícita era ralentizar las reparaciones.'),
('¿Qué resultado positivo apareció?','More beginners could work independently','Every repair became faster','Nobody had questions','Aumentó la autonomía para tareas simples, aunque se repararon menos equipos.'),
('¿Por qué se mantiene la propuesta?','Its learning benefit justifies further evaluation','It already solved every problem','The original concern was dishonest','El resultado mixto lleva a mantenerla y observar durante más tiempo.'),
('¿Qué falta según los comentarios?','A goal for the following week','A longer technical manual','A price for every repair','Algunos no sabían qué practicar después: hace falta acordar un objetivo.'),
('¿Qué debe conservar Mia?','The pictures','Printed copies of every draft','All the technical terms','El mensaje pide expresamente mantener las imágenes.'),
('¿Qué debe hacer ahora?','Prepare a draft for Thursday','Print copies immediately','Cancel the paired sessions','Debe preparar un borrador para hablar el jueves. No hace falta imprimir aún.'),
('Completa: Although repairs were slower, beginners ___ more confident.','became','becoming','have become yesterday','Became es el pasado de become y expresa el cambio durante ese periodo.'),
('Completa: The checklist helps them decide what ___ next.','to practise','practising','practised','What + infinitivo expresa una decisión pendiente: qué practicar.'),
('Acepta una sugerencia con una condición razonable.','That could work, as long as we review the results.','You are wrong and I will not listen.','We repaired computers last year.','La frase acepta la posibilidad y propone evaluar los resultados.')],
'Escribe 100–130 palabras a la coordinadora: resume los resultados, explica una dificultad y propone el siguiente paso.',
'En un minuto, propone una mejora para un grupo, anticipa una objeción y responde constructivamente.','Nora')
add('b2','Lo que una encuesta no demuestra',
'''A transport company surveyed passengers after introducing a quieter carriage on one of its commuter routes. Of the people who responded, 82 per cent said their journeys had improved. The company described this as strong evidence that quiet carriages should be introduced across the network. However, the survey link had been displayed mainly inside the new carriage, and responses were voluntary. Passengers who avoided the carriage were unlikely to see it. A local researcher welcomed the company's willingness to collect feedback but questioned whether the sample represented all passengers. She also pointed out that the trial had taken place during school holidays, when trains were less crowded. This did not mean the reported improvements were imaginary; it meant that the size and cause of the improvement remained uncertain. The company initially defended its conclusion, arguing that customers' experiences mattered more than technical criticism. After a public discussion, it agreed to run a second trial on three routes during term time. This time, staff would invite a selection of passengers from different carriages to respond, while recording crowding levels. The researcher supported the revised approach, although she warned that the results would still need careful interpretation. The disagreement shifted from whether quiet carriages were a good idea to what evidence would justify expanding them.''',
'''Una empresa encuestó a pasajeros tras introducir un vagón silencioso. El 82 % de quienes respondieron notó una mejora. La empresa lo tomó como evidencia para extenderlo, pero el enlace estaba sobre todo dentro de ese vagón y responder era voluntario. Otros pasajeros probablemente no lo vieron. Una investigadora valoró recoger opiniones, pero cuestionó la representatividad y recordó que la prueba se hizo en vacaciones, con menos aglomeración. No negaba las mejoras: señalaba incertidumbre sobre su tamaño y causa. Tras una discusión, acordaron otra prueba en tres rutas durante el periodo lectivo, con pasajeros de varios vagones y datos de ocupación. La investigadora apoyó el diseño con cautela. La discusión pasó de la conveniencia de la idea a la evidencia necesaria para ampliarla.''',
'''We are not postponing the second trial, but we are changing how we invite participants. Staff should approach every fifth passenger entering each selected carriage, rather than choosing people who seem willing to talk. If someone declines, record that and move on; do not replace them with a friend travelling beside them. This will not remove every source of bias, but it should make the selection more consistent.''',
'''No aplazamos la prueba; cambiamos cómo invitamos a participar. El personal debe acercarse a cada quinto pasajero que entre en cada vagón seleccionado, sin elegir a quienes parezcan dispuestos. Si alguien rechaza, anótenlo y continúen, sin sustituirlo por un amigo. No eliminará todos los sesgos, pero hará más consistente la selección.''',[
('¿Qué objeta principalmente la investigadora?','The evidence does not yet support such a broad conclusion','Passengers cannot judge their own journeys','Quiet carriages necessarily make journeys worse','Cuestiona generalizar a toda la red desde una muestra selectiva y condiciones particulares.'),
('¿Por qué importa dónde estaba el enlace?','It affected who was likely to respond','It changed ticket prices','It prevented all positive responses','La ubicación favorecía a quienes usaban el nuevo vagón: posible sesgo de selección.'),
('¿Qué función cumple mencionar las vacaciones?','It identifies another possible explanation for improvement','It proves the survey was fabricated','It establishes the best time to expand the scheme','Una ocupación menor podría influir en la experiencia; no prueba que los datos fueran inventados.'),
('¿Cómo termina el desacuerdo?','With a revised investigation and a more specific question','With agreement that expansion is already justified','With a decision never to use surveys','Se mejora el estudio y se precisa qué evidencia justificaría ampliarlo.'),
('¿Qué instrucción cambia en el mensaje?','How passengers are selected','The starting date of the trial','The number of routes','No se aplaza el inicio; cambia el método de selección.'),
('¿Qué hacer ante una negativa?','Record it without substituting a nearby friend','Automatically choose the person’s friend','Delete the invitation from the records','Registrar el rechazo conserva información sobre la participación.'),
('¿Cómo se presenta el nuevo método?','As an improvement with remaining limitations','As a guarantee of perfect representation','As unnecessary bureaucracy','«will not remove every source of bias» limita explícitamente el alcance.'),
('Completa: Had the sample been broader, the conclusion ___ more convincing.','might have been','might be being yesterday','will have','Had + sujeto + participio equivale a una condición pasada irreal. Might have been plantea un resultado posible.'),
('Resume el 82 % sin generalizar indebidamente.','Eighty-two per cent of respondents reported an improvement.','Eighty-two per cent of all passengers definitely benefited.','Every journey improved by eighty-two per cent.','Respondents conserva el denominador: quienes respondieron, no todos los pasajeros.'),
('Completa: The findings are promising; ___, they require further investigation.','nevertheless','therefore because','in order to','Nevertheless introduce contraste entre los resultados prometedores y la necesidad de investigar.')],
'Escribe 160–200 palabras para un boletín. Explica qué muestra la encuesta, qué no permite concluir y qué cambiarías en una segunda prueba.',
'En 90 segundos, defiende una prueba adicional. Reconoce los posibles beneficios y explica dos límites de la evidencia.','Max')
root=Path(__file__).resolve().parents[1]
(root/'src/assessments.json').write_text(json.dumps(items,ensure_ascii=False,indent=2))
print(len(items),'assessments;',sum(len(e['questions']) for e in items),'questions')
